        run: |
          set -euo pipefail
          target='data/recovery/canonical-ledger/corpus'
          rm -rf "$target"
          mkdir -p "$target/batches"
          cp data/recovery/canonical-knowledge-v2/manifest.json "$target/manifest.json"
          cp data/recovery/canonical-knowledge-v2/batches/*.json "$target/batches/"
          node <<'NODE'
          const fs=require('fs');
          const path=require('path');
          const root='data/recovery/canonical-ledger/corpus';
          const m=JSON.parse(fs.readFileSync(path.join(root,'manifest.json'),'utf8'));
          const files=fs.readdirSync(path.join(root,'batches')).filter(x=>x.endsWith('.json')).sort();
          if(files.length!==m.totalBatches) throw new Error('batch count mismatch');
          let records=0;
          for(const file of files){
            const value=JSON.parse(fs.readFileSync(path.join(root,'batches',file),'utf8'));
            const rows=Array.isArray(value)?value:(value.records||value.findings||[]);
            records+=rows.length;
          }
          if(records!==m.totalRecords) throw new Error(`record mismatch ${records} != ${m.totalRecords}`);
          fs.writeFileSync(path.join(root,'MATERIALIZATION_RECEIPT.json'),JSON.stringify({
            id:'pantavion_permanent_corpus_materialization_v1',
            generatedAt:new Date().toISOString(),
            totalRecords:m.totalRecords,
            totalBatches:m.totalBatches,
            corpusFingerprint:m.corpusFingerprint,
            countedBatchRecords:records,
            invariant:'Every manifest record is present in exactly one committed numbered batch.',
            tested:false,
            verified:false,
            deleteAllowed:false
          },null,2)+'\n');
          console.log(JSON.stringify({records,batches:files.length,fingerprint:m.corpusFingerprint}));
          NODE
