                    <p className="mt-2 text-xs leading-5 text-slate-300">
                      {layer.detail}
                    </p>
                    <p className="mt-3 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">
                      {active ? "workspace active" : "off"}
